                "F7A5 F7AF F7D3 F7DD F7F8 F801 F813 F838 F866 F86F "
                "F8A1 F8AA F8CF F8D8 F8FD F91A F948 F95F F976 F992 "
                "F9A9 F9C0 F9D7 F9EE FA0E FA3C FA44 FA53 FA6A FA90 "
                "FAD1 FAD5 FAD9 FB50 FB52 FB54 FB56 FB58 FB5A FB9D "
                "FC1E-FC23 FC84-FC86 FD2E-FD2F FD46 FD64 FD7B-FD7C FD8D FDB3 FDC2 FDE8 "
                "FDF7 FE72 FE8A FE9B FEAC FEDC FEEB FEFA FEFE FF28 "
                "FF37 FF51 FF60 FF6F"
